sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float amount;
uniform float radius;
half3 tap(float2 p)
{
    half4 s = image.eval(p);
    return s.rgb / max(s.a, 0.001);
}
half4 main(float2 coord)
{
    half4 c = image.eval(coord);
    if (c.a <= 0.001) return half4(0.0);
    half3 col = c.rgb / c.a;
    float r = radius;
    half3 avg = (tap(coord + float2(-r, -r)) + 2.0 * tap(coord + float2(0.0, -r)) + tap(coord + float2(r, -r))
        + 2.0 * tap(coord + float2(-r, 0.0)) + 4.0 * col + 2.0 * tap(coord + float2(r, 0.0))
        + tap(coord + float2(-r, r)) + 2.0 * tap(coord + float2(0.0, r)) + tap(coord + float2(r, r))) / 16.0;
    half3 sharpened = clamp(col + amount * (col - avg), 0.0, 1.0);
    return half4(sharpened * c.a, c.a);
}
